    /// A `size` px square element drawing the icon in `color` (0xRRGGBB).
    pub fn render(self, size: f32, color: Rgba) -> impl IntoElement {
        canvas(
            |_, _, _| (),
            move |bounds, _, window, _| {
                for stroke in self.0 {
                    let points = stroke
                        .iter()
                        .map(|[x, y]| {
                            bounds.origin
                                + point(
                                    bounds.size.width * (*x / 24.),
                                    bounds.size.height * (*y / 24.),
                                )
                        })
                        .collect::<Vec<_>>();
                    crate::paint::line(&points, 1.5, color, window);
                }
            },
        )
        .size(px(size))
    }
